  position: sticky;
  top: 48px;
  z-index: 24;
  background: rgba(245,245,247,.84);
  backdrop-filter: saturate(180%) blur(20px);
  border-block: 1px solid rgba(0,0,0,.06);
}
.section-nav-inner { max-width: 1180px; margin: 0 auto; padding: 10px 22px; display: flex; gap: 20px; overflow-x: auto; }
.section-nav a { min-height: 36px; white-space: nowrap; display: inline-flex; align-items: center; color: #3f3f46; font-size: 13px; }
.section-nav a:hover { color: var(--blue); }
.anchor-section { scroll-margin-top: 108px; }
.compare-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 18px; }
.setup-panel { background: #fff; border-radius: var(--radius-xl); padding: clamp(30px, 6vw, 74px); display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: center; box-shadow: var(--shadow); }
.setup-visual { min-height: 320px; border-radius: 28px; background: radial-gradient(circle at 30% 20%, #bbe6ff, transparent 36%), radial-gradient(circle at 72% 68%, #ffd9ba, transparent 36%), #f5f5f7; }

.entertainment { background: #fff; margin-top: 18px; padding: 64px 22px; }
.entertainment-inner { max-width: 1180px; margin: 0 auto; }
