  .product-grid, .hero-tile.large { grid-template-columns: 1fr; }
  .hero-tile, .hero-tile.large { grid-column: span 1; min-height: 560px; }
  .store-hero, .category-hero, .setup-panel { grid-template-columns: 1fr; }
  .support-stack { justify-self: stretch; max-width: none; }
  .info-grid, .compare-grid, .tab-panel.active { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
