  .brand span { display: none; }
  .nav-links { gap: 12px; font-size: 12px; }
  .nav-actions { display: none; }
  .hero-copy, .store-hero, .category-hero { padding-top: 42px; }
  .section { padding: 38px 16px; }
  .section-head.row { align-items: flex-start; flex-direction: column; }
  .product-grid { padding: 8px; gap: 8px; }
  .hero-tile, .hero-tile.large { min-height: 540px; padding: 36px 18px 24px; }
