  .phone { width: 112px; height: 232px; border-radius: 30px; }
  .laptop-screen { height: 224px; }
  .tablet { height: 260px; }
  .carousel-track { grid-auto-columns: minmax(282px, 84vw); gap: 14px; }
  .card { min-height: 430px; border-radius: 24px; padding: 23px; }
  .card.compact { min-height: 260px; }
  .footer-grid { display: block; padding: 8px 0 18px; }
  .footer-section { border-bottom: 1px solid rgba(0,0,0,.1); }
  .footer-toggle { min-height: 44px; display: flex; justify-content: space-between; align-items: center; cursor: pointer; }
  .footer-toggle::after { content: "+"; font-size: 18px; color: #6e6e73; }
  .footer-section.open .footer-toggle::after { content: "–"; }
  .footer-links { display: none; padding: 0 0 14px; }
  .footer-section.open .footer-links { display: grid; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; animation: none !important; }
